gQF(){return"\u0414\u0430. \u0416\u0438\u0442\u0435\u043b\u044f\u043c \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043d \u043f\u0440\u043e\u0435\u0437\u0434 \u043a \u0434\u043e\u043c\u0443. \u0412\u044a\u0435\u0437\u0436\u0430\u0442\u044c \u0438 \u0432\u044b\u0435\u0437\u0436\u0430\u0442\u044c \u043d\u0443\u0436\u043d\u043e \u043d\u0430 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u043c \u043a \u043d\u0435\u043c\u0443 \u043f\u0435\u0440\u0435\u043a\u0440\u0451\u0441\u0442\u043a\u0435."},
